import fs from 'node:fs'
import path from 'node:path'
import { pathToFileURL } from 'node:url'
import { describe, expect, it } from 'vitest'

/*
 * Auto-blur P3: the vendored libraries of the text rules (docs/design/auto-blur.md §6.14, §16.3,
 * test 135). The tarballs are pinned; scripts/vendor-privacy.mjs keeps them in .cache/privacy-vendor
 * and downloads them only when that copy is missing or wrong.
 */

const ROOT = path.resolve(__dirname, '..')
const VENDOR = path.join(ROOT, 'src', 'shared', 'privacy', 'vendor')

function filesUnder(dir: string): string[] {
  const out: string[] = []
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name)
    if (e.isDirectory()) out.push(...filesUnder(p))
    else out.push(p)
  }
  return out
}

describe('auto-blur P3: vendored libraries', () => {
  it('135. scripts/vendor-privacy.mjs --check passes and every vendored file carries its header', async () => {
    const script = (await import(pathToFileURL(path.join(ROOT, 'scripts', 'vendor-privacy.mjs')).href)) as {
      generate(): Promise<Record<string, string>>
      VENDOR_INPUTS: Record<string, { version: string; sha256: string; bytes: number; integrity: string; notice: string }>
      matchesPin(pin: unknown, bytes: Buffer): boolean
      withoutSourceMaps(text: string): string
    }
    // --check: every file is exactly what the script writes, and nothing else is in the folder.
    const files = await script.generate()
    const now = filesUnder(VENDOR).map((f) => path.relative(ROOT, f))
    expect(now.sort()).toEqual(Object.keys(files).sort())
    for (const [file, text] of Object.entries(files)) expect(fs.readFileSync(path.join(ROOT, file), 'utf8') === text, file).toBe(true)
    // 54 ES modules of libphonenumber-js and double-metaphone's one module (§6.14).
    expect(now.filter((f) => f.endsWith('.js') && f.includes('libphonenumber'))).toHaveLength(54)
    expect(now.filter((f) => f.endsWith('double-metaphone.js'))).toHaveLength(1)
    // Every file carries its GENERATED header, naming the package, version and SHA-256; no source map line is left.
    for (const f of now) {
      const text = fs.readFileSync(path.join(ROOT, f), 'utf8')
      expect(text.startsWith('/**\n * GENERATED by scripts/vendor-privacy.mjs'), f).toBe(true)
      expect(text).not.toMatch(/sourceMappingURL/)
      if (f.endsWith('.js')) {
        const pkg = f.includes('libphonenumber') ? 'libphonenumber-js' : 'double-metaphone'
        const pin = script.VENDOR_INPUTS[pkg]
        expect(text.slice(0, 600), f).toContain(`${pkg} ${pin.version}`)
        expect(text.slice(0, 600), f).toContain(`tarball SHA-256 ${pin.sha256}`)
        expect(text.slice(0, 600), f).toMatch(/package\/\S+, SHA-256 [0-9a-f]{64}/)
      }
    }
    // The pins are the design's, and a changed byte is refused.
    expect(script.VENDOR_INPUTS['libphonenumber-js']).toMatchObject({ version: '1.13.16', bytes: 1_908_294, sha256: '5cc6aa79db25ac97a730d110f47a1ed35cdeb8c53df48bed03b85d73a5205ba5' })
    expect(script.VENDOR_INPUTS['double-metaphone']).toMatchObject({ version: '2.0.1', bytes: 8_588, sha256: 'f069e40def102dd0b6c661040a6b72c88ec5c78900204716df4218d40249c1c3' })
    expect(script.matchesPin(script.VENDOR_INPUTS['double-metaphone'], Buffer.alloc(8_588))).toBe(false)
    expect(script.withoutSourceMaps('a\n//# sourceMappingURL=a.js.map')).toBe('a\n')
    // Each package's notice names it, its version and its tarball's hash, and holds its licence texts.
    for (const pin of Object.values(script.VENDOR_INPUTS)) {
      const notice = fs.readFileSync(path.join(ROOT, pin.notice), 'utf8')
      expect(notice.split('\n')[0]).toContain(pin.version)
      expect(notice).toContain(pin.sha256)
      expect(notice).toContain('Permission is hereby granted, free of charge')
    }
    expect(fs.readFileSync(path.join(ROOT, 'resources', 'notices', '38-libphonenumber-js.txt'), 'utf8')).toMatch(/Apache License\s+Version 2\.0, January 2004/)
    const gitleaks = fs.readFileSync(path.join(ROOT, 'resources', 'notices', '40-gitleaks-rules.txt'), 'utf8')
    expect(gitleaks).toContain('v8.30.1')
    expect(gitleaks).toContain('e163e53b9e7e8a8511e77271e2b323ed057759542a6d988258afe3a1fa329caf')
    expect(gitleaks).toContain('Copyright (c) 2019 Zachary Rice')
    // The notices are part of the third-party notices the app ships.
    const all = fs.readFileSync(path.join(ROOT, 'resources', 'THIRD_PARTY_NOTICES.txt'), 'utf8')
    for (const f of ['38-libphonenumber-js.txt', '39-double-metaphone.txt', '40-gitleaks-rules.txt']) expect(all).toContain(fs.readFileSync(path.join(ROOT, 'resources', 'notices', f), 'utf8').trim())
  }, 60_000)
})
